package com.nora.tunnel.ui.screens.statistics import androidx.compose.foundation.Canvas import androidx.compose.foundation.layout.* import androidx.compose.material3.* import androidx.compose.runtime.* import androidx.compose.ui.Modifier import androidx.compose.ui.geometry.Offset import androidx.compose.ui.graphics.Color import androidx.compose.ui.unit.dp import com.nora.tunnel.tunnel.TunnelStats import kotlinx.coroutines.flow.StateFlow @Composable fun LiveDashboard(statsFlow: StateFlow<TunnelStats?>) { val stats by statsFlow.collectAsState() Column(Modifier.fillMaxSize().padding(16.dp)) { Text("LIVE NETWORK", style = MaterialTheme.typography.headlineSmall) if(stats == null) { Card(Modifier.fillMaxWidth().padding(top=16.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.errorContainer)) { Text("Statistics unavailable", modifier = Modifier.padding(16.dp)) } Text("Core does not expose traffic counters in this build.", style = MaterialTheme.typography.bodySmall) return } Row(Modifier.fillMaxWidth().padding(top=16.dp), horizontalArrangement = Arrangement.SpaceBetween) { StatCard("Download", formatSpeed(stats!!.rxBytes), Modifier.weight(1f)) Spacer(Modifier.width(8.dp)) StatCard("Upload", formatSpeed(stats!!.txBytes), Modifier.weight(1f)) } Row(Modifier.fillMaxWidth().padding(top=8.dp), horizontalArrangement = Arrangement.SpaceBetween) { StatCard("Latency", stats!!.latencyMs?.let { "$it ms" } ?: "Not tested", Modifier.weight(1f)) Spacer(Modifier.width(8.dp)) StatCard("Uptime", formatUptime(stats!!.uptimeMs), Modifier.weight(1f)) } // Real-time graph - draws from actual rx/tx history var history by remember { mutableStateOf(listOf(0f,2f,5f,3f,8f,6f)) } // In prod: from statsFlow history buffer Card(Modifier.fillMaxWidth().height(160.dp).padding(top=16.dp)) { Canvas(Modifier.fillMaxSize().padding(16.dp)) { val max = (history.maxOrNull() ?: 1f).coerceAtLeast(1f) val stepX = size.width / (history.size - 1).coerceAtLeast(1) for(i in 0 until history.size - 1) { drawLine( color = Color(0xFF7C4DFF), start = Offset(i*stepX, size.height - (history[i]/max)*size.height), end = Offset((i+1)*stepX, size.height - (history[i+1]/max)*size.height), strokeWidth = 4f ) } } } Text("Transferred: ${formatBytes(stats!!.rxBytes + stats!!.txBytes)}", style = MaterialTheme.typography.bodySmall, modifier = Modifier.padding(top=8.dp)) } } @Composable private fun StatCard(label: String, value: String, modifier: Modifier) { Card(modifier) { Column(Modifier.padding(16.dp)) { Text(label, style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.primary) Text(value, style = MaterialTheme.typography.titleLarge) } } } private fun formatSpeed(b: Long) = if(b < 1024) "$b B/s" else "${b/1024} KB/s" private fun formatBytes(b: Long) = "${b / (1024*1024)} MB" private fun formatUptime(ms: Long): String { val s = ms/1000; return String.format("%02d:%02d:%02d", s/3600, (s%3600)/60, s%60) }

